/* 학습 해설
 * Min Heap Pop Push·개수 유지와한번의Sift
 * 최소를 제거한 자리에 새 원소를 바로 넣어 두 번의 heap 복구를 한 번으로 줄이는 원리를 배웁니다.
 * Pop_push는 root에 element를 memcpy하고 sift_down한번만수행합니다. Nr를 바꾸지않고 pop/push의 두복구를 합칩니다. Emptyguard나 capacity 변경은 없으므로 기존 heap에 최소원소가 있는 caller전제를 필요로합니다. Element가최소보다작아도최소교체연산의뜻으로 처리합니다.
 * 비어 있지 않은 heap과유효 sourceobject를 제공합니다. Emptyheap에새 원소를 등록하는 push대용이아닙니다. Top-K등의정책에서 는 새 원소를 교체할지 caller가결정하고 source가 copy대상과부적절하게겹치지않게합니다.
 */
void __min_heap_pop_push(min_heap_char *heap,
		const void *element, size_t elem_size,
		const struct min_heap_callbacks *func,
		void *args)
{
	memcpy(heap->data, element, elem_size);
	__min_heap_sift_down(heap, 0, elem_size, func, args);
}

#define min_heap_pop_push(_heap, _element, _func, _args)	\
	__min_heap_pop_push((min_heap_char *)_heap, _element, __minheap_obj_size(_heap), _func, _args)

/* Push an element on to the heap, O(log2(nr)). */
static __always_inline
bool __min_heap_push(min_heap_char *heap, const void *element, size_t elem_size,
		const struct min_heap_callbacks *func, void *args)
{
	void *data = heap->data;
	int pos;

	if (WARN_ONCE(heap->nr >= heap->size, "Pushing on a full heap"))
		return false;

	/* Place at the end of data. */
	pos = heap->nr;
	memcpy(data + (pos * elem_size), element, elem_size);

/* 학습 해설
 * Min Heap Push·끝에추가후상승
 * 배열 capacity 안에 새 원소를 복사하고 parent 경로에서 순서를 복구하는 방법을 배웁니다.
 * Nr>=size이면 WARN_ONCE후 false입니다. 성공하면 pos=nr 위치에 element를 memcpy하고 nr를 증가시킨뒤 sift_up합니다. 저장공간확장이나 allocation은 없습니다. Wrapper는 typed data의 원소크기를 전달하여 byteoffset을 계산합니다.
 * Init한 storage와올바른 capacity,element source의 폭과수명을 제공합니다. Full실패를 검사하고필요하면 caller가외부저장정책을 결정합니다. Capacity만크게고쳐실제 buffer밖에 push하지 않습니다.
 */
bool __min_heap_push(min_heap_char *heap, const void *element, size_t elem_size,
		const struct min_heap_callbacks *func, void *args)
{
	void *data = heap->data;
	int pos;

	if (WARN_ONCE(heap->nr >= heap->size, "Pushing on a full heap"))
		return false;

	/* Place at the end of data. */
	pos = heap->nr;
	memcpy(data + (pos * elem_size), element, elem_size);
	heap->nr++;

	/* Sift child at pos up. */
	__min_heap_sift_up(heap, elem_size, pos, func, args);

	return true;
}

#define min_heap_push(_heap, _element, _func, _args)	\
	__min_heap_push((min_heap_char *)_heap, _element, __minheap_obj_size(_heap), _func, _args)

/* Remove ith element from the heap, O(log2(nr)). */
static __always_inline
bool __min_heap_del(min_heap_char *heap, size_t elem_size, size_t idx,

/* 학습 해설
 * Min Heap Del·임의위치와양방향복구
 * 배열 중간 원소를 제거하고 마지막 원소로 채울 때 위와 아래의 순서 위반을 모두 처리합니다.
 * Del은 nr<=0이면 false입니다. Nr를 감소시키고 idx가이제 nr와같으면원래마지막 원소의삭제라즉시성공합니다. 나머지는 idx와기존마지막위치를 swap하고 idx의 sift_up다음 sift_down을 수행합니다. Body에는 idx<원래 nr 범위의명시적 guard가없으므로 caller가유효 idx를 제공합니다.
 * 존재하는 index만넘기고삭제 후 index가그 object의영구위치가아님을 확인합니다. Emptyguard를 임의 out-of-rangeindex보호로 해석하지 않습니다. Swapcallback과외부참조정책을 같이관리합니다.
 */
bool __min_heap_del(min_heap_char *heap, size_t elem_size, size_t idx,
		const struct min_heap_callbacks *func, void *args)
{
	void *data = heap->data;

	if (WARN_ONCE(heap->nr <= 0, "Popping an empty heap"))
		return false;

	/* Place last element at the root (position 0) and then sift down. */
	heap->nr--;
	if (idx == heap->nr)
		return true;
	func->swp(data + (idx * elem_size), data + (heap->nr * elem_size), args);
	__min_heap_sift_up(heap, elem_size, idx, func, args);
	__min_heap_sift_down(heap, idx, elem_size, func, args);

	return true;
}

#define min_heap_del(_heap, _idx, _func, _args)	\
	__min_heap_del((min_heap_char *)_heap, __minheap_obj_size(_heap), _idx, _func, _args)

#endif /* _LINUX_MIN_HEAP_H */

/* 학습 해설
 * Interval Span Merge·겹침과 인접 구간 합치기
 * 개별 node 구간 대신 연속 사용 영역과 빈 구간을 찾을 때 union 경계를 늘리는 원리를 배웁니다.
 * Nodes[1]에서 시작하여 nodes[0]에 현재 사용 span의 최대 last를 가진 node를 둡니다. 다음 겹침 node가 현재 last 안 또는 last+1에서 시작하면 같은 연속 span으로 합칩니다. 더 먼 끝을 발견하면 nodes[0]를 바꾸고, 처음 분리된 다음 span의 node를 nodes[1]로 남깁니다.
 * Nodes[1]이 비NULL이라는 내부 전제와 query 양끝을 유지합니다. Inclusive 끝점의 인접 관계를 사용하므로[2,4]와[5,7] 사이에 빈 정수 위치는 없습니다. Last+1의 unsigned 경계와 query clipping을 함께 읽습니다.
 */
interval_tree_span_iter_next_gap(struct interval_tree_span_iter *state)
{
	struct interval_tree_node *cur = state->nodes[1];

	state->nodes[0] = cur;
	do {
		if (cur->last > state->nodes[0]->last)
			state->nodes[0] = cur;
		cur = interval_tree_iter_next(cur, state->first_index,
					      state->last_index);
	} while (cur && (state->nodes[0]->last >= cur->start ||
			 state->nodes[0]->last + 1 == cur->start));
	state->nodes[1] = cur;
}

void interval_tree_span_iter_first(struct interval_tree_span_iter *iter,
				   struct rb_root_cached *itree,
				   unsigned long first_index,
				   unsigned long last_index)
{
	iter->first_index = first_index;
	iter->last_index = last_index;
	iter->nodes[0] = NULL;
	iter->nodes[1] =
		interval_tree_iter_first(itree, first_index, last_index);
	if (!iter->nodes[1]) {

/* 학습 해설
 * Interval Span First·전체 Hole와시작 Clip
 * 검색 범위가 전혀 쓰이지 않거나 사용 구간 중간에서 시작하는 경우의 첫 span을 구성합니다.
 * First는 query 양끝과 두 node 상태를 초기화합니다. 겹침 node가 없으면 전체 범위를 hole로 반환합니다. 첫 node.start가 query 시작 뒤이면 leading hole을 만들고 다음 used span을 merge해 준비합니다. 이미 사용 중이면 start_used=query 시작으로 clip하고 최대 끝을 last_index까지 제한합니다.
 * First_index<=last_index인 유효 inclusive 범위를 제공합니다. Is_hole과 해당 union field를 읽습니다. Used 끝이 query 끝에 닿으면 두 node를 NULL로 만들어 다음 호출의 종료를 준비합니다. 개별 node 대신 분류된 span을 얻는 API입니다.
 */
void interval_tree_span_iter_first(struct interval_tree_span_iter *iter,
				   struct rb_root_cached *itree,
				   unsigned long first_index,
				   unsigned long last_index)
{
	iter->first_index = first_index;
	iter->last_index = last_index;
	iter->nodes[0] = NULL;
	iter->nodes[1] =
		interval_tree_iter_first(itree, first_index, last_index);
	if (!iter->nodes[1]) {
		/* No nodes intersect the span, whole span is hole */
		iter->start_hole = first_index;
		iter->last_hole = last_index;
		iter->is_hole = 1;
		return;
	}
	if (iter->nodes[1]->start > first_index) {
		/* Leading hole on first iteration */
		iter->start_hole = first_index;
		iter->last_hole = iter->nodes[1]->start - 1;
		iter->is_hole = 1;
		interval_tree_span_iter_next_gap(iter);
		return;
	}

/* 학습 해설
 * Interval Span Next·Hole Used 교대와Done
 * 전체 요청 범위를 빈 구간과 사용 구간으로 빠짐없이 이어서 출력하는 상태 전이를 배웁니다.
 * 두 node가 NULL이면 is_hole=-1로 끝냅니다. Hole 상태에서는 last_hole+1부터 준비된 used 끝까지 출력하고 query 끝에 clip합니다. Used 상태에서 다음 span node가 없으면 현재 끝+1부터 query 끝까지 trailing hole입니다. 두 node가 모두 있으면 현재 끝+1과 다음 시작-1 사이의 interior hole을 출력하고 다음 used를 merge합니다.
 * First로 초기화한 iterator에서 done을 확인하며 진행합니다. Is_hole의0/1/-1을 bool 하나로 단순화하지 않습니다. 출력 span이 query 전체를 이어서 덮고 같은 위치를 중복 출력하지 않는 조건을 확인합니다.
 */
void interval_tree_span_iter_next(struct interval_tree_span_iter *iter)
{
	if (!iter->nodes[0] && !iter->nodes[1]) {
		iter->is_hole = -1;
		return;
	}

	if (iter->is_hole) {
		iter->start_used = iter->last_hole + 1;
		iter->last_used = iter->nodes[0]->last;
		if (iter->last_used >= iter->last_index) {
			iter->last_used = iter->last_index;
			iter->nodes[0] = NULL;
			iter->nodes[1] = NULL;
		}
		iter->is_hole = 0;
		return;
	}

	if (!iter->nodes[1]) {
		/* Trailing hole */
		iter->start_hole = iter->nodes[0]->last + 1;
		iter->last_hole = iter->last_index;
		iter->nodes[0] = NULL;
		iter->is_hole = 1;
		return;

/* 학습 해설
 * Interval Span Advance·현재범위 재사용과재검색
 * 이미 찾은 span 안의 새 시작점으로 이동할 때 tree를 다시 검색하지 않는 원리를 배웁니다.
 * Done이면 그대로 반환합니다. First_index를 new_index로 갱신하고 query 끝을 넘으면 done입니다. 현재 span 안이면 공유 start field만 new_index로 바꿉니다. 현재 끝+1이면 next 한 번으로 이동하고, 그 외에는 span_first를 new_index부터 다시 호출합니다. Hole/used field가 union으로 겹친다는 점을 이용합니다.
 * Iterator와 node 수명·tree 일관성을 유지합니다. Done 상태의 advance는 자동 restart가 아니므로 새 순회에는 first를 호출합니다. Forward 사용과 query 끝 경계를 확인하고 UL_MAX 근처의 끝+1 산술도 unsigned 조건과 함께 읽습니다.
 */
void interval_tree_span_iter_advance(struct interval_tree_span_iter *iter,
				     struct rb_root_cached *itree,
				     unsigned long new_index)
{
	if (iter->is_hole == -1)
		return;

	iter->first_index = new_index;
	if (new_index > iter->last_index) {
		iter->is_hole = -1;
		return;
	}

	/* Rely on the union aliasing hole/used */
	if (iter->start_hole <= new_index && new_index <= iter->last_hole) {
		iter->start_hole = new_index;
		return;
	}
	if (new_index == iter->last_hole + 1)
		interval_tree_span_iter_next(iter);
	else
		interval_tree_span_iter_first(iter, itree, new_index,
					      iter->last_index);
}
EXPORT_SYMBOL_GPL(interval_tree_span_iter_advance);
#endif

/* 학습 해설
 * 배열 교환·32비트 조각을 뒤에서 복사하기
 * 일반 구조체 전체를 고정된 크기의 조각으로 교환하는 반복문의 동작을 배웁니다.
 * n에서 4를 먼저 뺀 위치의 u32를 임시 변수에 저장합니다. 같은 위치의 b를 a에 복사한 뒤 임시 값을 b에 넣습니다. n이 0이 될 때까지 뒤쪽 조각에서 앞쪽 조각으로 진행합니다. 한 조각의 값을 먼저 보관해야 첫 번째 대입으로 덮어쓴 자료를 복원할 수 있습니다.
 * 호출자는 양수이며 4의 배수인 원소 크기와 설정에 맞는 접근 가능한 주소를 제공해야 합니다. 이 함수는 크기 0이나 임의의 바이트 수를 자체 검사하지 않습니다. 일반 응용 C에서는 정렬과 alias 규칙을 따르는 복사 방식을 따로 선택합니다.
 */
static void swap_words_32(void *a, void *b, size_t n)
{
	do {
		u32 t = *(u32 *)(a + (n -= 4));
		*(u32 *)(a + n) = *(u32 *)(b + n);
		*(u32 *)(b + n) = t;
	} while (n);
}

/**
 * swap_words_64 - swap two elements in 64-bit chunks
 * @a: pointer to the first element to swap
 * @b: pointer to the second element to swap
 * @n: element size (must be a multiple of 8)
 *
 * Exchange the two objects in memory.  This exploits base+index
 * addressing, which basically all CPUs have, to minimize loop overhead
 * computations.
 *
 * We'd like to use 64-bit loads if possible.  If they're not, emulating
 * one requires base+index+4 addressing which x86 has but most other
 * processors do not.  If CONFIG_64BIT, we definitely have 64-bit loads,
 * but it's possible to have 64-bit loads without 64-bit pointers (e.g.
 * x32 ABI).  Are there any cases the kernel needs to worry about?
 */
static void swap_words_64(void *a, void *b, size_t n)

/* 학습 해설
 * 배열 교환·64비트 설정과 두 번의 32비트 전송
 * 같은 8바이트 교환이 커널 설정에 따라 다른 명령 폭으로 구현되는 이유를 배웁니다.
 * CONFIG_64BIT 분기는 n을 8 줄인 뒤 u64 한 개를 교환합니다. 다른 분기는 n을 4씩 두 번 줄여 u32 두 개를 교환합니다. 두 방식 모두 한 반복에서 8바이트를 처리합니다. 주석은 64비트 전송을 흉내 낼 때 주소 계산 비용이 커질 수 있어 두 32비트 전송을 선택한 이유를 설명합니다.
 * 크기는 양수이며 8의 배수여야 합니다. 설정 분기의 산술과 자료 보존을 비교할 수 있지만 64비트 호스트에서 설정만 바꾼 시험을 실제 32비트 ABI나 해당 CPU의 성능 측정으로 표현하지 않습니다.
 */
static void swap_words_64(void *a, void *b, size_t n)
{
	do {
#ifdef CONFIG_64BIT
		u64 t = *(u64 *)(a + (n -= 8));
		*(u64 *)(a + n) = *(u64 *)(b + n);
		*(u64 *)(b + n) = t;
#else
		/* Use two 32-bit transfers to avoid base+index+4 addressing */
		u32 t = *(u32 *)(a + (n -= 4));
		*(u32 *)(a + n) = *(u32 *)(b + n);
		*(u32 *)(b + n) = t;

		t = *(u32 *)(a + (n -= 4));
		*(u32 *)(a + n) = *(u32 *)(b + n);
		*(u32 *)(b + n) = t;
#endif
	} while (n);
}

/**
 * swap_bytes - swap two elements a byte at a time
 * @a: pointer to the first element to swap
 * @b: pointer to the second element to swap
 * @n: element size
 *
 * This is the fallback if alignment doesn't allow using larger chunks.
 */

/* 학습 해설
 * 배열 교환·바이트 단위 대체 경로
 * 원소 크기나 주소가 넓은 전송 조건을 만족하지 않을 때 쓰는 대체 동작을 배웁니다.
 * n을 하나 줄인 바이트 위치에서 a와 b를 char 임시 변수로 교환합니다. 매번 한 바이트를 처리하므로 원소 크기가 4 또는 8의 배수일 필요가 없습니다. do-while이 첫 교환을 무조건 실행하므로 내부 함수에는 양수 크기 조건이 여전히 필요합니다.
 * sort_r는 원소 크기가 0이면 이 함수에 도달하기 전에 반환합니다. 작은 홀수 크기 구조와 주소 조건을 가진 배열의 교환을 관찰하되 배열 경계 밖 자료를 바꾸지 않는지 함께 확인합니다.
 */
static void swap_bytes(void *a, void *b, size_t n)
{
	do {
		char t = ((char *)a)[--n];
		((char *)a)[n] = ((char *)b)[n];
		((char *)b)[n] = t;
	} while (n);
}

/*
 * The values are arbitrary as long as they can't be confused with
 * a pointer, but small integers make for the smallest compare
 * instructions.
 */
#define SWAP_WORDS_64 (swap_r_func_t)0
#define SWAP_WORDS_32 (swap_r_func_t)1
#define SWAP_BYTES    (swap_r_func_t)2
#define SWAP_WRAPPER  (swap_r_func_t)3

struct wrapper {
	cmp_func_t cmp;
	swap_func_t swap;
};

/*
 * The function pointer is last to make tail calls most efficient if the
 * compiler decides not to inline this function.
 */

/* 학습 해설
 * 정렬 콜백·내장 교환 선택값과 priv 전달
 * 함수 포인터처럼 보이는 값 중 일부가 내부 선택 표식으로 사용되는 구조를 배웁니다.
 * SWAP_WORDS_64, SWAP_WORDS_32, SWAP_BYTES, SWAP_WRAPPER는 작은 정수를 함수 포인터 형식으로 변환한 내부 선택값입니다. do_swap은 먼저 표식을 비교해 실제 내부 함수를 호출합니다. 일반 콜백이면 마지막 인자로 priv를 전달합니다. WRAPPER이면 struct wrapper에 저장한 기존 형식의 콜백을 호출합니다. do_cmp도 비교 표식에 따라 기존 형식 또는 priv 형식을 선택합니다.
 * 공개 호출에는 정상적인 콜백 또는 NULL을 제공합니다. 내부 표식을 응용 코드의 호출 가능한 함수 주소로 취급하지 않습니다. 맞춤 교환 함수의 크기 인자는 int이므로 원소 크기의 표현 가능 범위도 호출자가 지켜야 합니다.
 */
static void do_swap(void *a, void *b, size_t size, swap_r_func_t swap_func, const void *priv)
{
	if (swap_func == SWAP_WRAPPER) {
		((const struct wrapper *)priv)->swap(a, b, (int)size);
		return;
	}

	if (swap_func == SWAP_WORDS_64)
		swap_words_64(a, b, size);
	else if (swap_func == SWAP_WORDS_32)
		swap_words_32(a, b, size);
	else if (swap_func == SWAP_BYTES)
		swap_bytes(a, b, size);
	else
		swap_func(a, b, (int)size, priv);
}

#define _CMP_WRAPPER ((cmp_r_func_t)0L)

static int do_cmp(const void *a, const void *b, cmp_r_func_t cmp, const void *priv)
{
	if (cmp == _CMP_WRAPPER)
		return ((const struct wrapper *)priv)->cmp(a, b);
	return cmp(a, b, priv);
}

