/* 학습 해설
 * sort·기존 콜백을 sort_r로 연결하는 래퍼
 * 문맥 인자가 없는 API와 있는 API가 같은 정렬 구현을 공유하는 방법을 배웁니다.
 * sort는 비교·교환 함수 포인터를 지역 struct wrapper에 저장하고 sort_r에 그 주소를 priv로 전달합니다. _CMP_WRAPPER와 SWAP_WRAPPER 표식은 do_cmp와 do_swap에 기존 형식 콜백을 선택하게 합니다. 교환 함수가 NULL이면 sort_r는 표식을 기본 교환 선택 경로로 바꿉니다. sort_r가 반환하기 전까지만 지역 wrapper를 사용하므로 주소를 장기 보관하지 않습니다.
 * 간단한 비교 기준에는 sort를, 외부 문맥이 필요한 기준에는 sort_r를 사용합니다. include/linux/sort.h는 두 함수 선언을 제공하고 linux/types.h의 콜백 형식에 연결됩니다. EXPORT_SYMBOL은 다른 커널 코드·모듈이 심볼을 사용할 수 있게 하는 표시이며 사용자 프로그램의 libc API와 구분합니다.
 */
void sort(void *base, size_t num, size_t size,
	  cmp_func_t cmp_func,
	  swap_func_t swap_func)
{
	struct wrapper w = {
		.cmp  = cmp_func,
		.swap = swap_func,
	};

	return sort_r(base, num, size, _CMP_WRAPPER, SWAP_WRAPPER, &w);
}
EXPORT_SYMBOL(sort);

/* 학습 해설
 * 연결 리스트 정렬·두 정렬된 열을 안정적으로 합치기
 * 배열 복사 없이 노드의 next 연결만 바꾸어 두 정렬된 열을 합치는 방법을 배웁니다.
 * a와 b는 각각 NULL로 끝나는 정렬된 노드 열입니다. 비교 결과가 0 이하이면 a를 먼저 연결하고, 양수이면 b를 먼저 연결합니다. tail은 마지막 노드 자체가 아니라 다음 포인터를 써야 할 위치를 가리킵니다. 한 열이 끝나면 다른 열의 나머지를 그대로 연결합니다. 같은 키에서 더 오래된 a를 먼저 선택하므로 입력 순서가 유지됩니다.
 * 이 내부 함수의 두 입력은 비어 있지 않아야 합니다. 중간 결과에는 sentinel head가 없고 prev 연결도 유지하지 않습니다. 공개 list_sort만 정상 원형 양방향 리스트를 입력받고 결과를 그 형태로 복원합니다.
 */
static struct list_head *merge(void *priv, list_cmp_func_t cmp,
				struct list_head *a, struct list_head *b)
{
	struct list_head *head, **tail = &head;

	for (;;) {
		/* if equal, take 'a' -- important for sort stability */
		if (cmp(priv, a, b) <= 0) {
			*tail = a;
			tail = &a->next;
			a = a->next;
			if (!a) {
				*tail = b;
				break;
			}
		} else {
			*tail = b;
			tail = &b->next;
			b = b->next;
			if (!b) {
				*tail = a;
				break;
			}
		}
	}
	return head;

/* 학습 해설
 * 연결 리스트 정렬·최종 병합과 원형 연결 복원
 * 마지막 병합에서 양방향 연결과 원형 head를 동시에 복원하는 원리를 배웁니다.
 * tail은 처음 head입니다. 선택한 노드를 tail->next에 연결하고 그 노드의 prev를 tail로 설정합니다. 한 열이 끝나면 남은 열을 이어 붙이면서 prev를 계속 복원합니다. 마지막 노드의 next를 head에 연결하고 head->prev를 마지막 노드로 설정하면 원형 양방향 구조가 완성됩니다.
 * 공개 함수가 반환한 뒤 next와 prev를 각각 순회해 서로 역순인지 확인합니다. 중간 병합에서 매번 prev를 고치거나 마지막에 별도 복원 순회를 하지 않고 최종 병합에 복원 작업을 결합한 설계입니다.
 */
static void merge_final(void *priv, list_cmp_func_t cmp, struct list_head *head,
			struct list_head *a, struct list_head *b)
{
	struct list_head *tail = head;
	u8 count = 0;

	for (;;) {
		/* if equal, take 'a' -- important for sort stability */
		if (cmp(priv, a, b) <= 0) {
			tail->next = a;
			a->prev = tail;
			tail = a;
			a = a->next;
			if (!a)
				break;
		} else {
			tail->next = b;
			b->prev = tail;
			tail = b;
			b = b->next;
			if (!b) {
				b = a;
				break;
			}
		}
	}

/* 학습 해설
 * 이진 최대공약수·0과 공통 2의 거듭제곱
 * 나눗셈 대신 가장 낮은 1비트를 이용하는 최대공약수 알고리즘의 바탕을 배웁니다.
 * gcd(a,b)는 두 부호 없는 정수의 최대공약수를 반환합니다. 둘 중 하나가 0이면 a|b를 반환하므로 다른 값이 그대로 나오고 둘 다 0이면 0입니다. 둘 다 양수일 때 r=a|b의 가장 낮은 1비트 위치는 두 수에 공통으로 포함된 2의 거듭제곱 지수입니다. r & -r는 그 공통 인수를 수치로 분리합니다.
 * 정수 비율이나 단위를 최대공약수로 약분할 때 사용합니다. 음수를 unsigned long으로 변환해서 같은 의미가 유지된다고 가정하지 않습니다. gcd(0,0)의 반환은 이 구현의 0이며 후속 나눗셈의 제수로 사용할 때 별도 조건을 확인합니다.
 */
unsigned long gcd(unsigned long a, unsigned long b)
{
	unsigned long r = a | b;

	if (!a || !b)
		return r;

	b >>= __ffs(b);
	if (b == 1)
		return r & -r;

	for (;;) {
		a >>= __ffs(a);
		if (a == 1)
			return r & -r;
		if (a == b)
			return a << __ffs(r);

		if (a < b)
			swap(a, b);
		a -= b;
	}
}

