/* 학습 해설
 * 고정 제수 나눗셈·느린 준비와 빠른 반복 계산
 * 제수가 자주 바뀌지 않을 때 나눗셈 준비 비용을 한 번 지불하고 반복 연산을 줄이는 방법을 배웁니다.
 * 양수 u32 제수 d에 대해 l=fls(d-1)은 ceil(log2(d))입니다. 준비 함수는 2^32*(2^l-d)를 d로 나누고 1을 더해 m을 만들며, sh1=min(l,1), sh2=max(l-1,0)을 저장합니다. 이 구조체를 반복 나눗셈에 재사용합니다. 준비에는 실제 나눗셈이 있으므로 제수마다 한 번만 계산하는 사용 흐름이 중요합니다.
 * 제수 0을 전달하지 않습니다. 제수가 바뀌면 새로운 구조체를 준비해야 합니다. 입력과 제수가 모두 u32인 부호 없는 정수 몫을 위한 방법이며 부동소수점 역수의 근삿값으로 결과를 추정하는 방식과 구분합니다.
 */
struct reciprocal_value reciprocal_value(u32 d)
{
	struct reciprocal_value R;
	u64 m;
	int l;

	l = fls(d - 1);
	m = ((1ULL << 32) * ((1ULL << l) - d));
	do_div(m, d);
	++m;
	R.m = (u32)m;
	R.sh1 = min(l, 1);
	R.sh2 = max(l - 1, 0);

	return R;
}
EXPORT_SYMBOL(reciprocal_value);

